"""Authored bilingual text from the supplied source sheets."""
def apply(g):
 p,book,en,tag=g['p'],g['book'],g['en'],g['TAG']
 def insert_before(key,n,title,title_en,pairs):
  b=book(key);en[title]=title_en
  page={'title':title,'blocks':[p(a,z)for a,z in pairs],'supplementId':tag,'sourceText':True}
  at=next((i for i,x in enumerate(b['pages'])if x.get('sourceLesson')==n),len(b['pages']));b['pages'].insert(at,page)
 insert_before('m02-c08',21,'DE LOS AIRES · DEL COMPASILLO','TEMPO · COMMON TIME',[
 ('<b>AIRE</b> es el que designa el grado de presteza o lentitud que debe llevar el compás. Se denota con una palabra italiana puesta al principio de una pieza o lección o en el discurso de ella.','<b>TEMPO</b> designates how quickly or slowly the metre should proceed. It is indicated by an Italian word at the beginning of a piece or lesson, or during it.'),
 ('Hay 4 aires principales, que son <i>Allegro</i> (aprisa), <i>Andante</i> (muy moderado), <i>Adagio</i> (despacio) y <i>Largo</i> (muy despacio). Las modificaciones que éstos reciben se hallarán en el discurso de estos solfeos, y en la tabla que está al fin.','There are four principal tempo indications: <i>Allegro</i> (fast), <i>Andante</i> (very moderate), <i>Adagio</i> (slow) and <i>Largo</i> (very slow). Their modifications will be found throughout these solfeggio lessons and in the table at the end.'),
 ('<b>DEL COMPASILLO</b><br/>El compás de <i>compasillo</i>, con cuyo solo nombre entendemos hoy el <i>cuaternario</i>, se divide en 4 partes o tiempos, se designa con esta señal <b>𝄴</b> y se marca con 4 movimientos de la mano en esta forma: <b>1 ↓ · 2 ← · 3 → · 4 ↑</b>; la 1ª y 3ª se llaman partes fuertes y la 2ª y 4ª débiles. (1) Entran el mismo número de figuras que en el compás <i>binario</i>; de consiguiente, la redonda vale un compás entero, que son 4 partes; la blanca medio, que son dos; y la negra un cuarto, que es una.','<b>COMMON TIME</b><br/>Common time, understood here as quadruple metre, divides into four beats. It is designated by <b>𝄴</b> and conducted with four hand movements: <b>1 ↓ · 2 ← · 3 → · 4 ↑</b>. The first and third beats are called strong, and the second and fourth weak. (1) It contains the same number of note values as the preceding duple metre: a whole note fills the four-beat measure, a half note fills two beats, and a quarter note fills one.'),
 ('(1) Las partes fuertes y débiles del compás son en música lo que las sílabas acentuadas e inacentuadas en el lenguaje.','(1) Strong and weak beats in music correspond to stressed and unstressed syllables in language.'),
 ('(2) Este <i>aire</i> no es tan despacio como muchos creen, sino un poco más lento que el <i>Allegro moderato</i> y nada más: así lo entendieron los antiguos, y este es el significado de la palabra <i>Andante</i> derivado del verbo <i>andare</i>, andar.','(2) This tempo is not as slow as many believe, but only a little slower than <i>Allegro moderato</i>: this is how earlier musicians understood <i>Andante</i>, derived from <i>andare</i>, to walk.')])
 insert_before('m08-c05',22,'PUNTO DE REPOSO · CALDERÓN','PAUSE · FERMATA',[
 ('<b>PUNTO DE REPOSO</b>, vulgarmente <b>CALDERÓN</b>, es un semicírculo con un punto en medio, que colocado debajo o encima de una nota o silencio, sirve para interrumpir momentáneamente el discurso musical, suspendiendo el compás: véase <b>𝄐</b>. (1)','A <b>FERMATA</b> is a semicircle with a dot in its centre. Placed above or below a note or rest, it momentarily suspends the musical flow and the metre: <b>𝄐</b>. (1)'),
 ('(1) También se le da el nombre italiano <i>Fermata</i> (detención); pero éste, además de significar el punto de reposo, incluye el caso de ejecutar la voz o instrumento algún paso <i>ad libitum</i>.','(1) The Italian term <i>fermata</i> means a stop. In this historical usage it may also include a passage performed <i>ad libitum</i> by the voice or instrument.')])
 insert_before('m04-c02',25,'DEL PUNTILLO','THE AUGMENTATION DOT',[
 ('El <b>PUNTILLO aumenta a la figura que lo tiene la mitad de su valor</b>: se coloca a la derecha de la nota; una <i>redonda</i>, cuyo valor es un compás, vale uno y medio con puntillo; la <i>blanca</i>, cuyo valor es dos partes, vale tres con puntillo y así de las demás.','An <b>augmentation dot adds half of the original note value</b>. It is placed to the right of the note. A whole note worth one measure is worth one and a half when dotted; a half note worth two beats is worth three when dotted, and similarly for other values.')])
 insert_before('m04-c02',26,'El silencio de negra','The quarter rest',[
 ('El <b>silencio de negra</b> se escribe así <b>𝄽</b> y se coloca en cualquier parte del pentagrama.','The <b>quarter rest</b> is written <b>𝄽</b> and may be placed on the staff.')])
 insert_before('m04-c02',34,'Negras con puntillo','Dotted quarter notes',[
 ('La negra, cuyo valor es una parte, vale una y media con puntillo.','A quarter note, whose value is one beat, is worth one and a half beats with a dot.')])
 insert_before('m04-c02',50,'Reducción de la Lección 34','Reduction of Lesson 34',[
 ('La corchea con puntillo vale media parte y la mitad más, o lo que es lo mismo, tres cuartos de parte. Téngase presente lo que se dijo al principio acerca del modo de facilitar la ejecución de las lecciones de reducción.','A dotted eighth note is worth half a beat plus half of that value, or three quarters of a beat. Keep in mind the earlier guidance on facilitating the performance of reduced-value lessons.')])
 insert_before('m04-c03',53,'DE LA SÍNCOPA','SYNCOPATION',[
 ('Llámanse <b>SONIDOS SINCOPADOS</b> a las notas que se dan a <i>contratiempo</i>. El resultado de las notas sincopadas es acentuar la parte <i>débil</i> del compás más que la <i>fuerte</i>; y como ésto sea invertir el orden natural, se dice que son a <i>contratiempo</i>. Hay síncopas <i>largas, muy largas, breves y muy breves</i>. Se escriben de 3 modos: 1º por medio de ligaduras; 2º por medio de notas partidas y 3º cortadas, por medio de pausas.','The source calls notes placed off the beat <b>SYNCOPATED SOUNDS</b>. They emphasize the weak part of the metre more than the strong part. It distinguishes long, very long, short and very short syncopations, written in three ways: with ties; with divided note values; and interrupted by rests.')])
 # Add drawing pages to the established clef lessons.
 for key,typ,title,eng in [('m10-c01','bass-writing','Así se escribe la clave de Fa','How to draw the bass clef'),('m10-c02','alto-writing','Así se escribe la clave de Do en tercera línea','How to draw the C clef on the third line')]:
  en[title]=eng;book(key)['pages'].append({'title':title,'blocks':[{'type':typ}],'supplementId':tag})
 translations={
 'Fa':'F','Do':'C','Escuchar Fa':'Listen to F','Escuchar Do':'Listen to C',
 '2 · Dibujamos la clave':'2 · Draw the clef','3 · Identificamos la línea de referencia':'3 · Identify the reference line','4 · Escribimos la nota de referencia':'4 · Write the reference note',
 'La clave de Fa en cuarta línea fija Fa3 en esa línea. Comienza con la cabeza sobre la cuarta línea, dibuja la curva y añade los dos puntos: uno en el espacio superior y otro en el inferior.':'The bass clef fixes F3 on the fourth line. Start with the head on that line, draw the curve and add the two dots, one in the space above and one below.',
 'Los dos puntos forman parte de la clave de Fa y rodean la cuarta línea.':'The two dots belong to the bass clef and surround the fourth line.',
 'La clave de Do en tercera línea fija Do4 en la línea central del pentagrama. Dibuja las dos barras verticales y los dos lóbulos. El centro del signo debe coincidir exactamente con la tercera línea.':'The C clef on the third line fixes C4 on the middle staff line. Draw the two vertical bars and the two lobes. The centre of the sign must align exactly with the third line.',
 'Los puntos naranjas son guías de la tercera línea; no forman parte de la clave de Do convencional.':'The orange dots are third-line guides; they are not part of the conventional C clef.'}
 en.update(translations)
